package com.example.cookpin.data;

import com.example.cookpin.R;
import java.util.Arrays;
import java.util.List;

public final class RecipeCatalog {
    public static final class Recipe {
        public final String id, title, ingredients, instructions, sourceUrl;
        public final int image, minutes, servings;
        Recipe(String id, String title, String ingredients, String instructions, int image, int minutes, int servings) {
            this(id, title, ingredients, instructions, image, minutes, servings, null);
        }

        Recipe(String id, String title, String ingredients, String instructions, int image, int minutes, int servings, String sourceUrl) {
            this.id = id;
            this.title = title;
            this.ingredients = ingredients;
            this.instructions = instructions;
            this.image = image;
            this.minutes = minutes;
            this.servings = servings;
            this.sourceUrl = sourceUrl;
        }
    }

    public static final List<Recipe> ALL = Arrays.asList(
        new Recipe("recipe1", "Pizza", "2 1/2 cups all-purpose flour\n1 cup warm water\n2 1/4 tsp active dry yeast\n1 tbsp olive oil\n1 tsp salt\n1/2 cup pizza sauce\n1 1/2 cups shredded mozzarella", "1. Stir yeast into warm water and let stand 5 minutes.\n2. Mix flour and salt; add yeast water and olive oil. Knead until smooth and let rise in a covered bowl for about 1 hour.\n3. Heat oven to 425°F. Stretch dough onto an oiled baking pan; for larger batches use extra pans so the crust stays thin. Spread sauce and add cheese.\n4. Bake 12–18 minutes until the crust is golden and cheese is bubbling.", R.drawable.recipe1, 95, 4),
        new Recipe("recipe2", "Chocolate Cake", "1 3/4 cups all-purpose flour\n2 cups granulated sugar\n3/4 cup unsweetened cocoa powder\n1 1/2 tsp baking powder\n1 1/2 tsp baking soda\n1 tsp salt\n2 eggs\n1 cup milk\n1/2 cup vegetable oil\n2 tsp vanilla extract\n1 cup hot water", "1. Heat oven to 350°F. Grease one 9-inch round pan for each half batch (two pans for the original recipe); bake in batches if needed.\n2. Whisk flour, sugar, cocoa, baking powder, baking soda and salt.\n3. Beat in eggs, milk, oil and vanilla; then stir in hot water. The batter will be thin.\n4. Divide evenly between pans, keeping the batter at the same depth. Bake each pan about 30–35 minutes, until a toothpick inserted in the center comes out clean. Cool before serving.", R.drawable.recipe2, 50, 12),
        new Recipe("recipe3", "Potato Soup", "4 medium russet potatoes\n1 medium onion\n2 tbsp butter\n4 cups vegetable broth\n1 cup heavy cream\n1/2 tsp salt\n1/4 tsp black pepper", "1. Peel and dice potatoes; finely chop onion.\n2. Melt butter in a pot and soften onion for 5 minutes.\n3. Add potatoes and broth. Simmer 15–20 minutes until potatoes are tender.\n4. Mash some of the potatoes to thicken the soup, stir in cream, salt and pepper, and warm gently without boiling.", R.drawable.recipe3, 40, 4),
        new Recipe("recipe4", "Chicken Enchiladas", "2 cups cooked shredded chicken\n8 small tortillas\n2 cups enchilada sauce\n1 1/2 cups shredded cheese", "1. Heat oven to 350°F. Spread one quarter of the sauce in a baking dish.\n2. Mix cooked chicken with another quarter of the sauce. Divide among tortillas, roll, and place seam-side down in the dish.\n3. Pour remaining sauce over tortillas, sprinkle with cheese, and bake 20–25 minutes until the center reaches 165°F.", R.drawable.recipe4, 40, 4),
        new Recipe("recipe5", "Chocolate Chip Cookies", "1 cup softened butter\n3/4 cup granulated sugar\n3/4 cup packed brown sugar\n2 eggs\n2 1/4 cups all-purpose flour\n1 tsp baking soda\n1 tsp salt\n2 cups chocolate chips", "1. Heat oven to 350°F and line baking sheets. Use more sheets or bake in batches when scaling up.\n2. Cream butter with both sugars. Beat in eggs.\n3. Mix in flour, baking soda and salt; fold in chocolate chips.\n4. Drop tablespoon-sized portions onto sheets with space between them. Bake 10–12 minutes until edges are golden. Cool on the pan for 5 minutes.", R.drawable.recipe5, 30, 24),
        new Recipe("recipe6", "Stir Fry", "1 tbsp olive oil\n1 red bell pepper\n1 yellow bell pepper\n1 cup sugar snap peas\n2 carrots\n1 cup sliced mushrooms\n2 cups broccoli florets\n1 cup baby corn\n1/2 cup sliced water chestnuts\n3 tbsp soy sauce\n2 garlic cloves\n1 tbsp brown sugar\n1 tsp sesame oil\n1/2 cup vegetable broth\n1 tbsp cornstarch", "1. Slice peppers and carrots; mince garlic. Whisk soy sauce, brown sugar, sesame oil, broth and cornstarch in a bowl.\n2. Heat olive oil in a large skillet or wok. Cook carrots and broccoli for 3 minutes.\n3. Add peppers, peas, mushrooms, baby corn, water chestnuts and garlic; cook 3–5 minutes until crisp-tender.\n4. Pour in sauce and stir until thickened and bubbling. Serve hot.", R.drawable.recipe6, 25, 4),
        new Recipe("recipe7", "Cauliflower Casserole", "1 head cauliflower\n2 tbsp butter\n1/2 cup grated Parmesan cheese\n1/2 cup bread crumbs\n1/2 tsp salt\n1/4 tsp red pepper flakes", "1. Heat oven to 350°F. Cut cauliflower into florets and steam about 10 minutes until just tender. Drain well.\n2. Combine melted butter, Parmesan, bread crumbs, salt and pepper flakes.\n3. Place cauliflower in a greased baking dish and scatter crumb mixture on top.\n4. Bake about 20 minutes until golden and hot.", R.drawable.recipe7, 40, 4),
        new Recipe("recipe8", "Pumpkin Pie", "1 unbaked 9-inch deep-dish pie shell\n1 can (15 oz each) pumpkin puree\n1 can (14 oz each) sweetened condensed milk\n2 large eggs\n1 tbsp pumpkin pie spice", "1. Heat oven to 425°F. Whisk pumpkin, condensed milk, eggs and spice until smooth.\n2. Pour filling into the unbaked pie shell. Bake at 425°F for 15 minutes.\n3. Lower oven to 350°F and bake another 40–50 minutes, until a knife inserted near the center comes out clean.\n4. Cool on a wire rack for about 2 hours before slicing. Refrigerate leftovers.", R.drawable.recipe8, 195, 8),
        new Recipe("recipe9", "Meatballs", "1 lb ground beef\n1/2 cup bread crumbs\n1/4 cup milk\n1/4 cup finely chopped onion\n2 tbsp chopped parsley\n1/4 cup grated Parmesan cheese\n1 egg\n1/2 tsp salt\n1/4 tsp black pepper", "1. Heat oven to 400°F and line a baking sheet.\n2. Mix beef, bread crumbs, milk, onion, parsley, Parmesan, egg, salt and pepper just until combined.\n3. Form small meatballs and arrange them in a single layer.\n4. Bake 18–22 minutes, checking that the centers reach 160°F with a food thermometer.", R.drawable.recipe9, 35, 4),
        // New recipes use original summaries and neutral artwork; sources are linked in the detail view.
        new Recipe("recipe10", "Buttermilk Pancakes", "2 cups all-purpose flour\n3 tbsp granulated sugar\n1 tsp baking powder\n1 tsp baking soda\n1/2 tsp salt\n1 large egg\n2 cups buttermilk\n2 tbsp melted butter\n1 1/2 tsp vanilla extract", "1. Whisk flour, sugar, baking powder, baking soda and salt in a large bowl.\n2. Beat the egg before measuring it if your batch calls for a fraction of an egg. Whisk the measured egg, buttermilk, melted butter and vanilla separately. Stir wet ingredients into dry until combined; a few lumps are fine. Rest 15 minutes.\n3. Warm and lightly grease a skillet over medium heat. Pour about 1/4 cup batter per pancake, leaving space between them.\n4. Cook until bubbles form and bottoms brown, about 1–2 minutes. Flip and cook 1–2 minutes more. Cook extra batches as needed.", R.drawable.ic_recipe_placeholder, 45, 8, "https://www.kingarthurbaking.com/recipes/buttermilk-pancakes-recipe"),
        new Recipe("recipe11", "Spinach Feta Egg Muffins", "10 large eggs\n1/2 cup cottage cheese\n1 cup finely chopped spinach\n1/2 cup crumbled feta cheese\n1/2 tsp salt\n1/4 tsp black pepper", "1. Heat oven to 375°F. Lightly grease enough muffin wells for about two muffins per serving. Divide spinach and feta between the wells.\n2. Blend eggs, cottage cheese, salt and pepper until smooth. Pour over the fillings without filling wells above the rim.\n3. Bake about 18 minutes until the centers are set and a thermometer inserted into an egg muffin reads 160°F. Bake additional trays in batches if needed.\n4. Let cool briefly in the tin, then loosen and transfer to a rack.", R.drawable.ic_recipe_placeholder, 33, 6, "https://www.budgetbytes.com/egg-muffins/"),
        new Recipe("recipe12", "French Toast", "6 thick slices slightly stale bread\n3 large eggs\n3/4 cup heavy cream\n2 tbsp granulated sugar\n1 tsp vanilla extract\n1/4 tsp ground nutmeg\n1 tbsp butter\n1 tbsp vegetable oil", "1. Heat oven to 400°F. Beat the eggs before measuring if your batch calls for a fraction of an egg. Whisk the measured eggs, cream, sugar, vanilla and nutmeg in a shallow dish.\n2. Dip bread for about 30 seconds per side, letting it absorb some custard without becoming soggy.\n3. Heat some butter and oil in a skillet over medium heat. Cook bread about 2 minutes on each side until golden. Repeat with remaining slices, adding the remaining fat as needed.\n4. Keep cooked slices on a baking sheet in the hot oven while finishing the rest; serve warm.", R.drawable.ic_recipe_placeholder, 31, 6, "https://www.kingarthurbaking.com/recipes/french-toast-recipe"),
        new Recipe("recipe13", "Shakshuka", "3 tbsp olive oil\n1 yellow onion\n1 red bell pepper\n2 jalapeno peppers\n5 celery ribs\n4 garlic cloves\n1 can fire-roasted diced tomatoes (14.5 oz)\n2 tbsp tomato paste\n2 tbsp smoked paprika\n1 1/2 tsp ground cardamom\n1 tsp ground cumin\n1 tsp dried oregano\n2 tsp sugar\n1 cup water\n4 large eggs\n1 tbsp lemon juice\n2 tsp salt", "1. Heat oven to 350°F. Dice onion, peppers and celery; mince garlic. In a wide ovenproof skillet, soften the vegetables in olive oil for about 10–12 minutes.\n2. Add garlic, paprika, cardamom, cumin and oregano. Stir briefly, then add tomatoes and their juices, tomato paste, sugar and lemon juice. Cook about 10 minutes; use some water to loosen the sauce.\n3. Make a well in the sauce for each egg and crack an egg into each well. If scaling up, divide sauce between ovenproof pans so eggs have room.\n4. Bake 8–12 minutes, then continue as needed until the whites and yolks are set and the egg centers reach 160°F on a food thermometer. Season with salt and serve.", R.drawable.ic_recipe_placeholder, 39, 4, "https://www.budgetbytes.com/shakshuka/"),
        new Recipe("recipe14", "Vegetarian Three-Bean Chili", "2 tbsp olive oil\n1 onion\n3 garlic cloves\n1 green bell pepper\n6 oz tomato paste\n1 can diced tomatoes (28 oz)\n1 can green chiles (4 oz)\n2 tbsp molasses\n1 cup water\n1 can kidney beans (15 oz)\n1 can black beans (15 oz)\n1 can pinto beans (15 oz)\n1 can corn kernels (15 oz)\n1 tbsp chili powder\n2 tsp ground cumin\n1/2 tsp black pepper\n1 tsp salt", "1. Dice onion and pepper; mince garlic. Drain and rinse beans and drain corn.\n2. Warm chili powder and cumin in a large pot over medium-low heat for about 2 minutes, stirring. Add oil, onion, pepper, garlic and salt; cook 4–6 minutes until softened.\n3. Stir in tomato paste, tomatoes with juices, green chiles, molasses, water and black pepper. Simmer about 5 minutes.\n4. Add beans and corn. Cover and gently simmer 20–25 minutes until vegetables are tender; stir occasionally. Use a larger pot or cook in batches when scaling up.", R.drawable.ic_recipe_placeholder, 50, 6, "https://www.budgetbytes.com/vegetarian-chili/"),
        new Recipe("recipe15", "One-Pot Vegetarian Chili Mac", "1 tbsp olive oil\n1 yellow onion\n2 garlic cloves\n2 tbsp all-purpose flour\n2 tbsp mild chili powder\n1 can diced tomatoes (15 oz)\n1 can tomato sauce (15 oz)\n1 can kidney beans (15 oz)\n1 can black beans (15 oz)\n1 can pinto beans (15 oz)\n1 cup frozen corn\n2 cups vegetable broth\n2 cups dry elbow macaroni\n1 cup shredded sharp cheddar", "1. Dice onion and mince garlic. Drain and rinse the beans. In a large pot, soften onion and garlic in olive oil over medium heat for about 3 minutes.\n2. Stir in flour and chili powder and cook about 2 minutes. Add tomatoes with juices, tomato sauce, beans, corn and broth; stir well.\n3. Add dry macaroni. Bring to a boil, stirring often, then reduce to a gentle simmer. Cook covered 12–15 minutes, stirring every few minutes, until pasta is tender and sauce thickens.\n4. Stir in cheddar off the heat until melted. For a larger batch, use a wide pot and allow extra time to return to a simmer.", R.drawable.ic_recipe_placeholder, 35, 8, "https://www.budgetbytes.com/cheesy-vegetarian-chili-mac/"),
        new Recipe("recipe16", "Black Bean Quesadillas", "1 can black beans (15 oz)\n1 cup frozen corn\n1/2 cup finely diced red onion\n1 garlic clove\n1/2 cup chopped cilantro\n2 cups shredded cheddar\n2 tbsp taco seasoning\n10 small flour tortillas", "1. Drain and rinse beans. Combine with corn, red onion, minced garlic, cilantro, cheddar and taco seasoning.\n2. Spoon about 1/2 cup filling on one side of each tortilla and fold in half.\n3. Cook in a dry skillet over medium heat, turning once, until both sides are golden and cheese melts. Cook in batches as needed and serve warm.", R.drawable.ic_recipe_placeholder, 15, 10, "https://www.budgetbytes.com/hearty-black-bean-quesadillas/"),
        new Recipe("recipe17", "Creamy Tomato Spinach Pasta", "1/2 lb dry penne pasta\n1 yellow onion\n2 garlic cloves\n1 tbsp olive oil\n1 can diced tomatoes (14.5 oz)\n1/2 tsp dried oregano\n1/2 tsp dried basil\n1/2 tsp salt\n2 tbsp tomato paste\n1/2 cup water\n2 oz cream cheese\n1/4 cup grated Parmesan\n4 oz fresh spinach", "1. Cook pasta in boiling water according to its package until tender, then drain.\n2. Meanwhile dice onion and mince garlic. Soften both in olive oil in a skillet over medium heat for 3–5 minutes.\n3. Add tomatoes and their juices, oregano, basil, salt, tomato paste and water. Simmer briefly, then reduce heat to low and stir in cream cheese and Parmesan until smooth.\n4. Stir in spinach until wilted, about 2–3 minutes. Toss with drained pasta and serve.", R.drawable.ic_recipe_placeholder, 25, 4, "https://www.budgetbytes.com/creamy-tomato-spinach-pasta/"),
        new Recipe("recipe18", "Tuscan White Bean Pasta", "8 oz dry linguine\n1 tbsp olive oil\n1 tbsp butter\n3 garlic cloves\n1 pint cherry tomatoes\n1/2 tsp salt\n1/2 tsp dried basil\n1 can cannellini beans (15 oz)\n4 oz baby spinach\n3 oz grated Parmesan", "1. Boil pasta according to its package, then drain. Rinse and drain beans; mince garlic.\n2. Heat oil and butter in a skillet over medium-low heat. Cook garlic for about 1 minute without letting it burn.\n3. Add tomatoes, salt and basil; cook until tomatoes burst and release their juices. Stir in spinach until partly wilted, then beans until hot.\n4. Toss in pasta and top with Parmesan. If increasing portions, use a skillet large enough to keep tomatoes in a shallow layer or cook in batches.", R.drawable.ic_recipe_placeholder, 30, 4, "https://www.budgetbytes.com/tuscan-white-bean-pasta/"),
        new Recipe("recipe19", "Vegetable Coconut Curry", "1 tbsp olive oil\n1 small onion\n4 garlic cloves\n1 tbsp freshly grated ginger\n1/2 cup broccoli florets\n1/2 cup diced carrots\n1/4 cup diced tomato\n1/3 cup snow peas\n1 tbsp mild curry powder\n2 cans light coconut milk (14 oz each)\n1 cup vegetable broth\n1/2 tsp salt", "1. Dice onion, mince garlic and cut vegetables into small pieces. Warm oil in a large saucepan over medium heat. Cook onion, garlic, ginger, carrots and broccoli for about 5 minutes.\n2. Stir in curry powder, coconut milk, broth and salt. Bring to a simmer and cook gently for 10–15 minutes.\n3. Add tomato and snow peas in the final 5 minutes so they stay crisp-tender. Taste and adjust seasoning. Serve over prepared rice or quinoa if desired.", R.drawable.ic_recipe_placeholder, 30, 4, "https://minimalistbaker.com/30-minute-coconut-curry/"),
        new Recipe("recipe20", "Tomato Soup", "2 tbsp olive oil\n2 tbsp unsalted butter\n2 medium yellow onions\n2 medium carrots\n6 garlic cloves\n2 tbsp balsamic vinegar\n2 cans diced tomatoes, 28 oz each\n3 cups vegetable broth\n1 1/3 cups heavy cream\n1 tsp dried thyme\n1/2 tsp red pepper flakes\n1 tsp salt", "1. Chop the onions, carrots and garlic. Warm the oil and butter in a large pot, then soften the vegetables for about 8 minutes.\n2. Stir in the vinegar. Add tomatoes with their juices, broth, cream, thyme, pepper flakes and salt. Simmer 20–25 minutes, until the carrots soften.\n3. Let cool slightly. Blend some of the soup for a creamy texture, working carefully in batches if needed, then combine with the remaining soup. Taste and adjust seasoning before serving.", R.drawable.ic_recipe_placeholder, 45, 6, "https://www.loveandlemons.com/tomato-soup-recipe/"),
        new Recipe("recipe21", "Chicken Noodle Soup", "1 medium yellow onion\n3 garlic cloves\n4 carrots\n2 celery ribs\n1 tbsp chopped parsley\n2 tbsp olive oil\n1 tsp dried basil\n1/2 tsp dried thyme\n1 bay leaf\n1/4 tsp black pepper\n1 tsp salt\n2 boneless skinless chicken breasts\n8 cups chicken broth\n6 oz dry egg noodles", "1. Dice the onion, carrots and celery; mince the garlic. Heat oil in a large pot and soften the onion, carrot and celery for about 6 minutes. Add garlic, basil, thyme, bay leaf, pepper and salt; stir for another 5 minutes.\n2. Add chicken and broth. Bring to a boil, then cover and maintain a gentle simmer for about 1 hour. Check that the chicken reaches 165°F in the thickest part.\n3. Lift out the chicken, shred it and discard the bay leaf. Boil the noodles in the broth until tender, about 7 minutes. Return chicken to the pot, add parsley and season to taste.", R.drawable.ic_recipe_placeholder, 105, 8, "https://www.budgetbytes.com/chicken-noodle-soup/"),
        new Recipe("recipe22", "Greek Salad", "1/4 cup olive oil\n3 tbsp red wine vinegar\n1 garlic clove\n1/2 tsp dried oregano\n1/4 tsp Dijon mustard\n1/4 tsp salt\n1 English cucumber\n1 green bell pepper\n2 cups cherry tomatoes\n5 oz feta cheese\n1/3 cup sliced red onion\n1/3 cup pitted Kalamata olives\n1/3 cup fresh mint leaves", "1. Whisk oil, vinegar, minced garlic, oregano, mustard and salt into a dressing.\n2. Seed and slice the cucumber, chop the pepper, halve the tomatoes and cube the feta.\n3. Toss cucumber, pepper, tomatoes, feta, onion and olives gently with the dressing. Scatter mint over the top and serve.", R.drawable.ic_recipe_placeholder, 15, 4, "https://www.loveandlemons.com/greek-salad/"),
        new Recipe("recipe23", "Tuna Salad", "2 cans chunk light tuna in water, 12 oz each\n1 cup diced celery\n1/4 cup chopped walnuts\n2 green onions\n1/2 cup mayonnaise\n1 tbsp lemon juice\n1/4 tsp black pepper\n1/4 tsp salt", "1. Drain the tuna thoroughly. Dice the celery, chop walnuts and slice the green onions.\n2. Mix tuna, vegetables and walnuts with mayonnaise, lemon juice, pepper and salt until evenly coated.\n3. Serve chilled on bread, over greens or with crackers. Refrigerate leftovers promptly.", R.drawable.ic_recipe_placeholder, 10, 4, "https://www.budgetbytes.com/classic-tuna-salad/"),
        new Recipe("recipe24", "Lemon Herb Baked Salmon", "2 lb salmon fillet\n5 rosemary sprigs\n2 small lemons\n2 tbsp olive oil\n1 tsp kosher salt\n1/4 tsp black pepper\n4 garlic cloves", "1. Heat oven to 375°F. Line a rimmed pan with foil. Slice part of the lemon and arrange some slices and rosemary beneath the salmon. Reserve the remaining lemon for juice.\n2. Rub salmon with oil, salt and pepper. Scatter chopped garlic and remaining rosemary and lemon slices over it; squeeze the reserved lemon on top. Fold foil into a loose packet.\n3. Bake 15–20 minutes, checking the thickest part. Uncover carefully to avoid steam; broil briefly if a golden top is wanted. Fish is ready at 145°F or when opaque and easily flaked. Divide into portions.", R.drawable.ic_recipe_placeholder, 35, 6, "https://www.wellplated.com/baked-salmon-in-foil/"),
        new Recipe("recipe25", "Beef Tacos", "12 taco shells\n1 tbsp cooking oil\n2 garlic cloves\n1 yellow onion\n1 lb ground beef\n2 tbsp tomato paste\n1/4 cup water\n1 tsp garlic powder\n1 tsp onion powder\n1 tsp dried oregano\n2 tsp ground cumin\n2 tsp paprika\n1 tsp salt\n2 tomatoes\n1 cup shredded lettuce\n1/2 cup shredded cheddar", "1. Mince garlic and onion. Mix garlic powder, onion powder, oregano, cumin, paprika and salt. Chop tomatoes and lettuce for topping.\n2. Heat oil in a skillet. Cook onion and garlic until softened, then add beef and break it into small pieces. Stir in spices and cook until the meat reaches 160°F.\n3. Add tomato paste and water; simmer briefly until the filling is juicy but no longer watery. Warm taco shells according to their package. Fill with beef, tomato, lettuce and cheddar.", R.drawable.ic_recipe_placeholder, 30, 4, "https://www.recipetineats.com/ground-beef-tacos-recipe/"),
        new Recipe("recipe26", "Apple Crisp", "3 lb apples\n2 tbsp lemon juice\n1/2 cup packed brown sugar\n2 tbsp melted butter\n1 tsp cinnamon\n3 tbsp all-purpose flour\n1/4 tsp salt\n3/4 cup all-purpose flour\n1/2 cup quick oats\n2/3 cup packed brown sugar\n1 tsp cinnamon\n3/4 tsp baking powder\n8 tbsp cold unsalted butter", "1. Heat oven to 350°F. Grease baking dishes; use enough dishes to keep the apple layer similar in depth when changing the batch size. Peel, core and slice apples.\n2. Toss apples with lemon juice, the first brown sugar, melted butter, the first cinnamon, the first flour amount and salt. Spread in the dishes.\n3. Mix the remaining flour, oats, brown sugar, cinnamon and baking powder. Rub in cold butter until crumbs form; distribute evenly over apples.\n4. Bake on a lined sheet for about 55–65 minutes, until fruit bubbles and topping turns golden. Cool at least 20 minutes before serving.", R.drawable.ic_recipe_placeholder, 95, 8, "https://www.kingarthurbaking.com/recipes/classic-apple-crisp-recipe"),
        new Recipe("recipe27", "Sheet Pan Chicken Fajitas", "1 tbsp chili powder\n1 1/2 tsp paprika\n1/2 tsp onion powder\n1/4 tsp garlic powder\n1/4 tsp ground cumin\n1 tsp sugar\n1/2 tsp salt\n2 small yellow onions\n3 bell peppers\n1 lb boneless skinless chicken breast\n2 tbsp cooking oil\n1 lime\n8 small tortillas", "1. Heat oven to 400°F. Mix chili powder, paprika, onion powder, garlic powder, cumin, sugar and salt. Cut onion, peppers and chicken into thin strips.\n2. Toss chicken and vegetables with oil and spice mix. Spread in one layer over as many baking sheets as needed so the strips are not crowded.\n3. Start checking after 20 minutes, stirring the pan once. Remove when chicken reaches 165°F and peppers soften, usually within 20–40 minutes depending on strip thickness. Squeeze lime over the pan and serve in warmed tortillas.", R.drawable.ic_recipe_placeholder, 55, 4, "https://www.budgetbytes.com/oven-fajitas/"),
        new Recipe("recipe28", "Banana Bread", "4 medium yellow bananas\n1 cup packed brown sugar\n1/2 cup vegetable oil\n1 large egg\n2 tsp vanilla extract\n2 cups all-purpose flour\n1 tsp baking powder\n1/2 tsp baking soda\n1/2 tsp salt\n2 tbsp coarse sugar", "1. Grease and line loaf pans. Put peeled banana pieces and brown sugar in a roasting pan. Place in the oven as it heats to 325°F; roast 20–25 minutes, stirring occasionally, until soft and syrupy.\n2. Mash the hot bananas in a bowl and cool 5 minutes. Whisk in oil, egg and vanilla, then fold in flour, baking powder, baking soda and salt. For scaled batches, beat the egg first and measure the indicated fraction; split batter among pans to keep the same depth.\n3. Sprinkle with coarse sugar. Bake about 45–50 minutes per loaf, until a skewer comes out clean. Cool in pans for 15 minutes, then cool completely on racks before slicing.", R.drawable.ic_recipe_placeholder, 100, 10, "https://www.kingarthurbaking.com/recipes/sneaky-shortcut-banana-bread-recipe"),
        new Recipe("recipe29", "Broccoli Salad", "1 lb broccoli florets\n1/2 cup sunflower seeds\n1/2 cup finely chopped red onion\n1/2 cup shredded sharp cheddar\n1/3 cup dried cranberries\n1/3 cup olive oil\n2 tbsp apple cider vinegar\n1 tbsp Dijon mustard\n1 tbsp honey\n1 garlic clove\n1/4 tsp salt", "1. Toast sunflower seeds in a dry skillet over medium heat for about 5 minutes, stirring until lightly golden. Transfer to a bowl.\n2. Chop broccoli into small pieces and add to the seeds with onion, cheddar and cranberries.\n3. Whisk oil, vinegar, mustard, honey, minced garlic and salt. Toss with the vegetables and chill for at least 20 minutes before serving.", R.drawable.ic_recipe_placeholder, 40, 6, "https://cookieandkate.com/favorite-broccoli-salad-recipe/")
    );

    public static Recipe find(String id) {
        for (Recipe recipe : ALL) {
            if (recipe.id.equals(id)) return recipe;
        }
        return null;
    }

    private RecipeCatalog() {}
}
